#!/usr/bin/env bash
# Rocky Chess trusted bootstrap for a fresh Debian 12 host. No existing data deletion.
set +x
set -Eeuo pipefail
umask 077
REPO='https://github.com/ansinlia/Rocky-Chess.git'
APP='/opt/xiaoi-staging-app'
STATE='/opt/xiaoi-state'
INSTALLER_DOWNLOAD_TMP=''
# Only the exact clone directory generated by this launch may be removed.
installer_cleanup_own_temp(){
  local path="${INSTALLER_DOWNLOAD_TMP:-}"
  [[ -n "$path" ]] || return 0
  if [[ ! "$path" =~ ^/opt/\.rocky-gh-[A-Za-z0-9]{8}$ ]]; then
    echo '清理警告：本次临时目录名称异常，不执行删除。' >&2
    return 0
  fi
  [[ -e "$path" || -L "$path" ]] || return 0
  if [[ -L "$path" || ! -d "$path" || "$(stat -c '%u:%g:%a' -- "$path")" != '0:0:700' ]]; then
    echo "清理警告：目录身份或权限异常，不执行删除：$path" >&2
    return 0
  fi
  if rm -rf --one-file-system -- "$path"; then
    echo '清理完成：本次 GitHub 临时下载目录已删除。'
  else
    echo "清理未完成：请核查本次暂存目录：$path" >&2
  fi
}
installer_cleanup_report(){
  local count=0 pending=0
  echo '===== 安装器残留检查（只读） ====='
  if [[ -d /opt && ! -L /opt ]]; then
    count="$(find /opt -mindepth 1 -maxdepth 1 -type d -name '.rocky-gh-????????' -printf '.' | wc -c)" || count=unknown
  fi
  if [[ "$count" == 0 ]]; then
    echo 'GitHub 下载暂存目录：无残留。'
  else
    echo "GitHub 历史暂存目录：$count 个；来源未经确认，不自动删除。"
  fi
  if [[ -e /root/rocky-backup-tools-update.py || -L /root/rocky-backup-tools-update.py ]]; then
    echo '备份工具安装暂存文件：存在，可能需要续装；未删除。'
  else
    echo '备份工具安装暂存文件：无残留。'
  fi
  if [[ -d /etc/rocky-chess && ! -L /etc/rocky-chess ]]; then
    pending="$(find /etc/rocky-chess -mindepth 1 -maxdepth 1 -type f \
      \( -name '.first-baseline-????????' -o -name '.restic-reentry-????????' \) \
      -printf '.' | wc -c)" || pending=unknown
  fi
  if [[ "$pending" == 0 ]]; then
    echo '安装临时状态文件：无残留。'
  else
    echo "安装临时状态文件：$pending 个；未删除，避免破坏续装。"
  fi
  echo 'APT 缓存及 Docker 镜像层：属于系统缓存，不执行全局清理。'
  echo '网站、数据库、密钥、Restic 仓库、服务及回滚文件：全部保留。'
}
installer_finish(){
  local original_status=$?
  trap - EXIT
  installer_cleanup_own_temp || true
  installer_cleanup_report || true
  [[ "$original_status" -eq 0 ]] || echo "安装入口退出码：$original_status；未完成步骤请按原模式续装。"
  exit "$original_status"
}
trap installer_finish EXIT
trap 'exit 130' INT
trap 'exit 143' TERM


fatal(){ printf '安装暂停：%s\n' "$*" >&2; exit 2; }
note(){ printf '\n===== %s =====\n' "$*"; }
[[ $# == 1 && ( "$1" == '--fresh-staging' || "$1" == '--restore-staging' || "$1" == '--restore-production' ) ]] || fatal '用法：sudo bash rocky-chess-start.sh --fresh-staging｜--restore-staging｜--restore-production'
[[ "$EUID" -eq 0 ]] || fatal '请在 VPS 的 root 终端运行。'
[[ -t 0 && -t 1 ]] || fatal '请通过交互式终端运行，不要在无人值守脚本中启动。'
source /etc/os-release
[[ "${ID:-}" == debian && "${VERSION_ID:-}" == 12 ]] || fatal '当前仅支持 Debian 12。'
[[ "$(dpkg --print-architecture)" == amd64 ]] || fatal '当前仅支持 x86_64/amd64。'
grep -qm1 ' avx2 ' /proc/cpuinfo || fatal '服务器 CPU 缺少 Stockfish18 所需的 AVX2。'
[[ ! -L "$APP" && ! -L "$STATE" ]] || fatal '网站程序或数据路径是符号链接，拒绝继续。'

note '步骤 1 / 6：准备 GitHub 私有仓库访问'
printf '请在电脑浏览器打开： https://github.com/ansinlia/Rocky-Chess\n'
printf '新建/查看只读 Fine-grained token：https://github.com/settings/personal-access-tokens/new\n'
printf '只授权 Rocky-Chess 仓库的 Contents: Read。无需删除旧仓库或已有密钥。\n'
printf 'Token 只用来下载程序，不写进 Git 地址、脚本、日志或磁盘配置。\n'
if [[ ! -e "$APP" ]]; then
  export DEBIAN_FRONTEND=noninteractive
  apt-get update
  apt-get install -y --no-install-recommends git ca-certificates python3
  printf 'Git 会提示输入 GitHub Username，以及 Password（此处粘贴只读 Token，输入不回显）。\n'
  printf '无需将 Token 写入脚本、命令参数或任何磁盘凭据文件。\n'
  tmpdir="$(mktemp -d /opt/.rocky-gh-XXXXXXXX)"
  INSTALLER_DOWNLOAD_TMP="$tmpdir"
  [[ -d "$tmpdir" && ! -L "$tmpdir" ]] || fatal '临时目录不安全'
  printf '正在通过 Git 官方交互认证下载 private main 分支……\n'
  if ! env -u GIT_ASKPASS -u SSH_ASKPASS GIT_TERMINAL_PROMPT=1 \
     git -c credential.helper= -c core.askPass= clone --depth 1 --branch main "$REPO" "$tmpdir/release"; then
    fatal 'GitHub 下载失败。已安排清理本次下载暂存目录；请检查只读 Token 的仓库权限。'
  fi
  release="$tmpdir/release"
  [[ -f "$release/deploy/rocky-chess-wizard.sh" && -f "$release/deploy/one-click-debian12.sh" && -f "$release/compose.yaml" ]] ||
    fatal 'GitHub main 尚未包含完整的交互式安装程序。不会安装旧版本。'
  [[ "$(git -C "$release" remote get-url origin)" == "$REPO" ]] || fatal 'GitHub 仓库来源不符'
[[ "$(git -C "$release" rev-parse --abbrev-ref HEAD)" == main ]] || fatal '仅接受已审核的 main 分支'
grep -Fq 'Rocky Chess 中文交互菜单' "$release/deploy/rocky-chess-wizard.sh" &&
grep -Fq 'choose_restore_source(){' "$release/deploy/rocky-chess-wizard.sh" &&
grep -Fq 'FIRST_PRODUCTION_BACKUP_VERIFIED' "$release/deploy/install-site-ops-debian12.sh" ||
  fatal 'GitHub main 仍是旧版或缺少安全恢复流程；禁止继续安装，请先完成审核合并'
  [[ "$(git -C "$release" status --porcelain | wc -c)" -eq 0 ]] || fatal '仓库内容有未预期改动'
  chmod 0700 "$release"
  [[ ! -e "$APP" && ! -L "$APP" ]] || fatal '目标程序目录在下载期间出现，拒绝覆盖'
  mv -- "$release" "$APP"
  rmdir "$tmpdir"
  INSTALLER_DOWNLOAD_TMP=''
  printf 'GitHub 下载成功；以后重试不会重新覆盖目录。\n'
else
  [[ -d "$APP" && ! -L "$APP" && -d "$APP/.git" ]] || fatal '已有程序目录身份无法确认，拒绝覆盖'
  [[ "$(git -C "$APP" remote get-url origin)" == "$REPO" ]] || fatal '现存程序目录不是指定的私有仓库'
  [[ -f "$APP/deploy/rocky-chess-wizard.sh" ]] || fatal '现存程序目录缺少向导文件'
  grep -Fq 'Rocky Chess 中文交互菜单' "$APP/deploy/rocky-chess-wizard.sh" &&
  grep -Fq 'choose_restore_source(){' "$APP/deploy/rocky-chess-wizard.sh" &&
  grep -Fq 'FIRST_PRODUCTION_BACKUP_VERIFIED' "$APP/deploy/install-site-ops-debian12.sh" ||
    fatal '现存程序不是经过新菜单及恢复审查的版本；保留目录，请人工核实来源'
  [[ -z "$(git -C "$APP" status --porcelain)" ]] ||
    fatal '现存程序目录有未提交改动；拒绝继续，防止混用不同版本'
  printf '检测到先前下载并通过安全版本校验的程序；继续使用，不强制拉取或覆盖已有版本。\n'
fi

cd "$APP"
bash "$APP/deploy/rocky-chess-wizard.sh" "$1"
